import { Component, OnDestroy } from '@angular/core';
import { Router } from '@angular/router';
import { Geolocation, Geoposition } from '@awesome-cordova-plugins/geolocation/ngx';
import { TextToSpeechAdvanced } from '@awesome-cordova-plugins/text-to-speech-advanced/ngx';
import { LoadingController } from '@ionic/angular';
import { Subscription } from 'rxjs';
import { G } from 'src/app/core/common/G';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { Urls } from 'src/app/core/common/Urls';
import { CourseService } from 'src/app/data/service/course/course.service';
import { SliderService } from 'src/app/data/service/site/Slider.service';

type GpsStatus = 'off' | 'connecting' | 'ready' | 'weak' | 'error';
type SprintState = 'idle' | 'armed' | 'running' | 'completed';

interface SpeedSample {
  speedKmh: number;
  atMs: number;
}

interface PositionSample {
  lat: number;
  lon: number;
  accuracy: number | null;
  atMs: number;
}

@Component({
  selector: 'app-speedometer',
  templateUrl: './speedometer.component.html',
  styleUrls: ['./speedometer.component.scss'],
})
export class SpeedometerPage implements OnDestroy {
  isCheck = true;
  hasAccess = false;
  queryText = '';
  showSearchbar = false;
  unit: 'kmh' | 'mph' = 'kmh';

  gpsStatus: GpsStatus = 'off';
  gpsMessage = 'برای نمایش سرعت، موقعیت مکانی را فعال کن.';
  isTracking = false;
  hasFix = false;
  speedEstimated = false;
  lastFixAt: number | null = null;
  lat: number | null = null;
  long: number | null = null;
  speed: number | null = null;
  heading: number | null = null;
  altitudeAccuracy: number | null = null;
  altitude: number | null = null;
  accuracy: number | null = null;

  testState: SprintState = 'idle';
  timer0to100 = '0.00';
  last0to100Seconds: number | null = null;
  testMessage = 'از حالت توقف شروع کن؛ زمان‌سنج با حرکت خودرو فعال می‌شود.';

  private nativeWatch: Subscription | null = null;
  private browserWatchId: number | null = null;
  private gpsWatchdog: ReturnType<typeof setInterval> | null = null;
  private sprintTimer: ReturnType<typeof setInterval> | null = null;
  private sprintStartedAt = 0;
  private previousSpeedSample: SpeedSample | null = null;
  private previousPosition: PositionSample | null = null;
  private trackingStartedAt = 0;

  constructor(
    private geolocation: Geolocation,
    private router: Router,
    public loadingController: LoadingController,
    private siteService: SliderService,
    private tts: TextToSpeechAdvanced,
    private courseService: CourseService
  ) {
    this.check();
  }

  get speedKmh(): number | null {
    return this.speed === null ? null : Math.max(0, this.speed * 3.6);
  }

  get mainSpeed(): number | null {
    const kmh = this.speedKmh;
    return kmh === null ? null : Math.round(this.unit === 'kmh' ? kmh : kmh / 1.609344);
  }

  get secondarySpeed(): number | null {
    const kmh = this.speedKmh;
    return kmh === null ? null : Math.round(this.unit === 'kmh' ? kmh / 1.609344 : kmh);
  }

  get speedProgress(): number {
    return Math.min(100, (this.speedKmh || 0) / 240 * 100);
  }

  get headingLabel(): string {
    if (this.heading === null) { return '—'; }
    const directions = ['شمال', 'شمال‌شرق', 'شرق', 'جنوب‌شرق', 'جنوب', 'جنوب‌غرب', 'غرب', 'شمال‌غرب'];
    return directions[Math.round(this.heading / 45) % 8];
  }

  get gpsStatusLabel(): string {
    const labels: Record<GpsStatus, string> = {
      off: 'GPS خاموش',
      connecting: 'در حال دریافت موقعیت',
      ready: 'موقعیت آماده',
      weak: 'دقت پایین',
      error: 'خطای موقعیت'
    };
    return labels[this.gpsStatus];
  }

  ionViewWillEnter(): void {
    if (this.hasAccess && !this.isTracking) { this.startTracking(); }
  }

  ionViewWillLeave(): void {
    this.stopTracking();
  }

  ngOnDestroy(): void {
    this.stopTracking();
  }

  async check(): Promise<void> {
    SharedIonic.loading(this.loadingController);
    this.siteService.GetTunerPlusById(26).subscribe(
      res => {
        if (res.status !== GResponse.SuccessStatus || !res.data.isActive) {
          this.denyAccess();
          return;
        }
        if (res.data.isFree) {
          this.grantAccess();
          return;
        }
        this.courseService.GetUserCoursesId().subscribe(
          courses => {
            const ownsCourse = courses.status === GResponse.SuccessStatus &&
              res.data.courseIds.some(courseId => courses.data.some(id => String(id) === String(courseId)));
            if (!ownsCourse) {
              this.denyAccess();
              return;
            }
            this.courseService.GetUserTunerPlusAccess().subscribe(
              access => access.status === GResponse.SuccessStatus ? this.grantAccess() : this.denyAccess(),
              () => this.denyAccess()
            );
          },
          () => this.denyAccess()
        );
      },
      () => this.denyAccess()
    );
  }

  private grantAccess(): void {
    SharedIonic.dismissLoading(this.loadingController);
    this.isCheck = false;
    this.hasAccess = true;
    this.startTracking();
  }

  private denyAccess(): void {
    SharedIonic.dismissLoading(this.loadingController);
    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
  }

  startTracking(): void {
    if (!this.hasAccess || this.isTracking) { return; }
    this.gpsStatus = 'connecting';
    this.gpsMessage = 'در انتظار اجازه و نخستین موقعیت GPS…';
    this.hasFix = false;
    this.lastFixAt = null;
    this.previousPosition = null;
    this.previousSpeedSample = null;
    this.isTracking = true;
    this.trackingStartedAt = Date.now();

    try {
      if (G.IsAndroid) {
        this.nativeWatch = this.geolocation.watchPosition({
          enableHighAccuracy: true, maximumAge: 0, timeout: 15000
        }).subscribe(
          data => {
            if (data && 'coords' in data && data.coords) {
              this.handlePosition(data as Geoposition);
            } else {
              this.handleGpsError(data);
            }
          },
          error => this.handleGpsError(error)
        );
      } else if (typeof navigator !== 'undefined' && navigator.geolocation) {
        this.browserWatchId = navigator.geolocation.watchPosition(
          position => this.handlePosition(position),
          error => this.handleGpsError(error),
          { enableHighAccuracy: true, maximumAge: 0, timeout: 15000 }
        );
      } else {
        this.handleGpsError({ code: 2 });
        return;
      }

      if (!this.isTracking) { return; }
      this.gpsWatchdog = setInterval(() => {
        const lastSignalAt = this.lastFixAt === null ? this.trackingStartedAt : this.lastFixAt;
        if (this.isTracking && Date.now() - lastSignalAt > 15000) {
          this.gpsStatus = 'weak';
          this.gpsMessage = 'دادهٔ GPS تازه دریافت نشده؛ در فضای باز دوباره تلاش کن.';
          this.speed = null;
          this.hasFix = false;
          if (this.testState === 'armed' || this.testState === 'running') {
            this.cancelSprint('ارتباط GPS قطع شد؛ آزمون لغو شد.');
          }
        }
      }, 5000);
    } catch (error) {
      this.handleGpsError(error);
    }
  }

  stopTracking(): void {
    this.clearWatch();
    this.isTracking = false;
    this.hasFix = false;
    this.speed = null;
    this.gpsStatus = 'off';
    this.gpsMessage = 'GPS متوقف شده است.';
    if (this.testState === 'armed' || this.testState === 'running') {
      this.cancelSprint('GPS متوقف شد؛ آزمون لغو شد.');
    }
  }

  private clearWatch(): void {
    if (this.nativeWatch) { this.nativeWatch.unsubscribe(); this.nativeWatch = null; }
    if (this.browserWatchId !== null && typeof navigator !== 'undefined' && navigator.geolocation) {
      navigator.geolocation.clearWatch(this.browserWatchId);
      this.browserWatchId = null;
    }
    if (this.gpsWatchdog) { clearInterval(this.gpsWatchdog); this.gpsWatchdog = null; }
  }

  private handleGpsError(error: any): void {
    this.clearWatch();
    this.isTracking = false;
    this.hasFix = false;
    this.speed = null;
    this.gpsStatus = 'error';
    this.gpsMessage = error && error.code === 1
      ? 'دسترسی به موقعیت مکانی رد شد؛ مجوز GPS را در تنظیمات مرورگر یا دستگاه فعال کن.'
      : error && error.code === 3
        ? 'دریافت موقعیت به‌موقع انجام نشد؛ در فضای باز دوباره تلاش کن.'
        : 'موقعیت مکانی در دسترس نیست؛ GPS و اتصال دستگاه را بررسی کن.';
    if (this.testState === 'armed' || this.testState === 'running') {
      this.cancelSprint('GPS در دسترس نیست؛ آزمون لغو شد.');
    }
  }

  private handlePosition(position: Geoposition | GeolocationPosition): void {
    if (!this.isTracking) { return; }
    const coords = position.coords;
    if (!Number.isFinite(coords.latitude) || !Number.isFinite(coords.longitude)) { return; }
    const now = performance.now();
    const accuracy = Number.isFinite(coords.accuracy) ? coords.accuracy : null;
    const nativeSpeed = coords.speed;
    const hasNativeSpeed = typeof nativeSpeed === 'number' && Number.isFinite(nativeSpeed) && nativeSpeed >= 0;
    const measuredSpeed = hasNativeSpeed ? nativeSpeed : this.estimateSpeed(coords.latitude, coords.longitude, accuracy, now);

    this.lat = coords.latitude;
    this.long = coords.longitude;
    this.accuracy = accuracy;
    this.altitude = coords.altitude !== null && Number.isFinite(coords.altitude) ? coords.altitude : null;
    this.altitudeAccuracy = coords.altitudeAccuracy !== null && Number.isFinite(coords.altitudeAccuracy) ? coords.altitudeAccuracy : null;
    this.heading = coords.heading !== null && Number.isFinite(coords.heading) && coords.heading >= 0 ? coords.heading : null;
    this.speed = measuredSpeed;
    this.speedEstimated = !hasNativeSpeed && measuredSpeed !== null;
    this.hasFix = true;
    this.lastFixAt = Date.now();
    if (!this.previousPosition || hasNativeSpeed || now - this.previousPosition.atMs >= 1000) {
      this.previousPosition = { lat: coords.latitude, lon: coords.longitude, accuracy, atMs: now };
    }

    const precise = accuracy !== null && accuracy <= 30;
    this.gpsStatus = precise && hasNativeSpeed ? 'ready' : 'weak';
    this.gpsMessage = !precise
      ? 'دقت موقعیت برای آزمون ۰ تا ۱۰۰ کافی نیست؛ به فضای باز برو.'
      : !hasNativeSpeed
        ? 'سرعت از جابه‌جایی موقعیت تخمین زده شده و برای آزمون مناسب نیست.'
        : 'موقعیت و سرعت GPS دریافت می‌شود.';

    if ((this.testState === 'armed' || this.testState === 'running') && (!precise || !hasNativeSpeed)) {
      this.cancelSprint('دقت GPS افت کرد؛ آزمون لغو شد.');
      return;
    }
    if (precise && hasNativeSpeed) {
      this.handleSprintSample(Math.max(0, measuredSpeed * 3.6), now);
    }
  }

  private estimateSpeed(lat: number, lon: number, accuracy: number | null, now: number): number | null {
    const previous = this.previousPosition;
    if (!previous || accuracy === null || accuracy > 30 ||
        previous.accuracy === null || previous.accuracy > 30) { return null; }
    const seconds = (now - previous.atMs) / 1000;
    if (seconds < 1) { return null; }
    const toRadians = Math.PI / 180;
    const dLat = (lat - previous.lat) * toRadians;
    const dLon = (lon - previous.lon) * toRadians;
    const a = Math.sin(dLat / 2) ** 2 +
      Math.cos(previous.lat * toRadians) * Math.cos(lat * toRadians) * Math.sin(dLon / 2) ** 2;
    const meters = 6371000 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    const metersPerSecond = meters / seconds;
    return metersPerSecond <= 90 ? metersPerSecond : null;
  }

  setUnit(next: 'kmh' | 'mph'): void {
    this.unit = next;
  }

  onStart0to100(): void {
    const currentSpeed = this.speedKmh;
    if (!this.isTracking || this.gpsStatus !== 'ready' || this.lastFixAt === null ||
        Date.now() - this.lastFixAt > 5000 || currentSpeed === null || currentSpeed > 2) {
      this.testMessage = 'برای شروع، GPS دقیق و سرعت کمتر از ۲ کیلومتر بر ساعت لازم است.';
      return;
    }
    this.testState = 'armed';
    this.timer0to100 = '0.00';
    this.testMessage = 'آمادهٔ حرکت؛ زمان‌سنج از لحظهٔ عبور از ۳ کیلومتر بر ساعت آغاز می‌شود.';
    this.previousSpeedSample = { speedKmh: currentSpeed, atMs: performance.now() };
  }

  onStop0to100(): void {
    this.cancelSprint('آزمون لغو شد؛ برای تلاش دوباره از حالت توقف شروع کن.');
  }

  private cancelSprint(message: string): void {
    if (this.sprintTimer) { clearInterval(this.sprintTimer); this.sprintTimer = null; }
    this.testState = 'idle';
    this.timer0to100 = '0.00';
    this.testMessage = message;
  }

  private handleSprintSample(speedKmh: number, atMs: number): void {
    const previous = this.previousSpeedSample;
    if (this.testState === 'armed' && speedKmh >= 3) {
      const fraction = previous && speedKmh > previous.speedKmh
        ? Math.max(0, Math.min(1, (3 - previous.speedKmh) / (speedKmh - previous.speedKmh))) : 1;
      this.sprintStartedAt = previous ? previous.atMs + fraction * (atMs - previous.atMs) : atMs;
      this.testState = 'running';
      this.testMessage = 'در حال اندازه‌گیری تا ۱۰۰ کیلومتر بر ساعت…';
      this.sprintTimer = setInterval(() => {
        this.timer0to100 = ((performance.now() - this.sprintStartedAt) / 1000).toFixed(2);
      }, 100);
    }
    if (this.testState === 'running' && speedKmh >= 100) {
      const fraction = previous && speedKmh > previous.speedKmh
        ? Math.max(0, Math.min(1, (100 - previous.speedKmh) / (speedKmh - previous.speedKmh))) : 1;
      const finishedAt = previous ? previous.atMs + fraction * (atMs - previous.atMs) : atMs;
      const seconds = Math.max(0, (finishedAt - this.sprintStartedAt) / 1000);
      if (this.sprintTimer) { clearInterval(this.sprintTimer); this.sprintTimer = null; }
      this.last0to100Seconds = Math.round(seconds * 100) / 100;
      this.timer0to100 = this.last0to100Seconds.toFixed(2);
      this.testState = 'completed';
      this.testMessage = 'آزمون کامل شد. نتیجهٔ GPS تخمینی است و به نرخ نمونه‌برداری دستگاه وابسته است.';
      if (G.IsAndroid && G.voice) { this.tts.speak('100').catch(() => undefined); }
    }
    this.previousSpeedSample = { speedKmh, atMs };
  }

  search(): void {
    if (!this.queryText) { return; }
    this.router.navigate(['Home', 'Search'], { queryParams: { title: this.queryText } });
  }

  onCancel(): void {
    this.showSearchbar = false;
  }
}
